3	// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
4	// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
5	export type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';
6	
7	// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
8	// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
9	type PendingSignup = { email: string; firstName: string; lastName: string };
