11	type UseSubscribeSectionParams = {
12	  /** Forces the post-submit success state up front. For Storybook/tests only. */
13	  initialSubscribed?: boolean;
14	  /** Opt in to the HPC-035 name-capture modal instead of the placeholder path. */
15	  enableNameCapture?: boolean;
16	};
17	
18	type UseSubscribeSectionReturn = {
19	  submitState: SubmitState;
20	  modalOpen: boolean;
21	  closeModal: () => void;
22	  handleEmailSubmit: (email: string) => void;
23	  handleModalSubmit: (firstName: string, lastName: string) => void;
24	};
